const reviewPane=$('[data-ss-pane="review"]');if(reviewPane){const mistakes=frequentMistakes().slice(0,12);reviewPane.innerHTML=`<h3>Spaced review queue</h3><div class="ss-list">${due.length?due.map(reviewItemHtml).join(''):'<div class="ss-empty">Nothing due today. In Learn/Review mode, use <b>Review later</b> on a question.</div>'}</div><h3 style="margin-top:18px">Frequent mistakes</h3><p>Calculated from your saved exam attempts.</p><div class="ss-list">${mistakes.length?mistakes.map(x=>`<div class="ss-list-item"><div class="ss-grow"><b>${x.type==='listening'?'Listening':'Reading'} ${x.number} · Q${x.q+1}</b><small>Missed ${x.misses} time${x.misses===1?'':'s'} across saved attempts.</small></div><button class="ss-secondary ss-mini" data-study-id="${esc(x.id)}" data-study-q="${x.q}">Study</button></div>`).join(''):'<div class="ss-empty">Finish some mock exams and your repeated mistakes will appear here.</div>'}</div>`}
