function refreshCommandCenter(){const cc=$('.study-command-center');if(!cc)return;const s=scoreStats(),today=suite.activity[TODAY()]||{questions:0,actions:0},goal=Math.max(1,+suite.dailyGoal||30),pct=Math.min(100,Math.round((today.questions||0)/goal*100));cc.innerHTML=`<div class="ss-command-head"><div><h2>🧠 Your TCF command center</h2><p>Everything is stored locally on this device.</p></div><div class="spacer"></div><button class="ss-secondary ss-mini" data-cc-hub>Open Study Hub</button></div><div class="ss-command-grid"><div class="ss-metric"><b>${streak()}</b><span>day study streak</span></div><div class="ss-metric"><b>${s.completed}</b><span>mock attempts saved</span></div><div class="ss-metric"><b>${s.avg||'—'}${s.avg?'%':''}</b><span>average latest accuracy</span></div><div class="ss-metric"><b>${esc(s.weakest)}</b><span>current focus skill</span></div><div class="ss-metric ss-goal"><div class="ss-goal-ring" style="--p:${pct}"><b>${pct}%</b></div><div><b style="font-size:16px">Today: ${today.questions||0}/${goal} questions</b><span>${dueItems().length} spaced review${dueItems().length===1?'':'s'} due · Target NCLC ${suite.targetNclc}</span></div></div><div class="ss-metric ss-goal"><div style="font-size:28px">📚</div><div><b style="font-size:16px">Smart review ready</b><span>${frequentMistakes().length} question${frequentMistakes().length===1?'':'s'} identified from attempt history</span></div></div></div>`;const b=$('[data-cc-hub]');if(b)b.onclick=()=>openDrawer('today')}
function enhanceHome(){const hero=$('.hero');if(!hero)return;if(!$('.study-command-center')){const el=document.createElement('section');el.className='study-command-center';hero.insertAdjacentElement('beforebegin',el)}refreshCommandCenter()}
