function addQuestionTools(){const mode=currentMode();if(mode!=='learning'&&mode!=='review')return;const head=$('.exam-head');if(!head||$('.ss-question-tools',head))return;const c=currentExamContext();if(!c)return;const key=`${c.exam.id}:q${c.q+1}`,bookmarked=(suite.bookmarks||[]).some(x=>x.key===key),queued=(suite.reviewQueue||[]).some(x=>x.key===key);const wrap=document.createElement('div');wrap.className='ss-question-tools';wrap.innerHTML=`<button class="ss-question-tool ${bookmarked?'active':''}" data-ss-bookmark>${bookmarked?'★ Bookmarked':'☆ Bookmark'}</button><button class="ss-question-tool ${queued?'active':''}" data-ss-review-later>${queued?'✓ Review queued':'↻ Review later'}</button><button class="ss-question-tool" data-ss-note>📝 Note</button>`;head.appendChild(wrap);$('[data-ss-bookmark]',wrap).onclick=toggleBookmark;$('[data-ss-review-later]',wrap).onclick=toggleReviewLater;$('[data-ss-note]',wrap).onclick=()=>openDrawer('notes')}
function toggleBookmark(){const c=currentExamContext();if(!c)return;const key=`${c.exam.id}:q${c.q+1}`,i=suite.bookmarks.findIndex(x=>x.key===key);if(i>=0)suite.bookmarks.splice(i,1);else suite.bookmarks.push({key,examId:c.exam.id,type:c.type,number:c.number,q:c.q,label:(c.exam.questions[c.q]?.prompt||c.exam.questions[c.q]?.content||'Question').slice(0,110),saved:TODAY()});saveSuite();lastSignature='';enhanceCurrent()}
