function enhanceWriting(){if(currentMode()!=='writing')return;$$('.subject-block').forEach(block=>{if($('.ss-practice-btn',block))return;const h=$('h2',block);if(!h)return;const btn=document.createElement('button');btn.className='ss-practice-btn';btn.type='button';btn.textContent='✍️ Practice';btn.onclick=()=>openWritingLab(block);h.appendChild(btn)})}
function detectWritingTask(){const t=$('.lesson-header h1')?.textContent||$('.document-side .active')?.textContent||'';const m=t.match(/(?:Tâche|Task)\s*([123])/i);return m?+m[1]:1}
