function openWritingLab(block){const task=detectWritingTask(),bounds=writingBounds(task),num=(block.id||'sujet').replace(/\D+/g,'')||'x',key=`writing:t${task}:s${num}`,prompt=$('.prompt-text',block)?.innerText?.trim()||'',draft=suite.drafts[key]||'';openLabModal(`Writing Lab · Tâche ${task}`,`Official target: ${bounds[0]}–${bounds[1]} words · TCF Canada writing total: 60 minutes`,`<div class="ss-lab-grid"><div><div class="ss-prompt">${esc(prompt)}</div><div class="ss-counter"><b>Draft</b><span class="ss-word-status" data-word-status></span></div><div class="ss-progressbar"><i data-word-bar></i></div><textarea class="ss-editor" data-writing-editor placeholder="Write your French response here…">${esc(draft)}</textarea><div class="ss-row" style="margin-top:9px;flex-wrap:wrap"><button class="ss-primary" data-save-draft>Save draft</button><button class="ss-secondary" data-copy-draft>Copy</button><button class="ss-secondary" data-analyze-writing>🔬 Analyze locally</button><button class="ss-danger" data-clear-draft>Clear</button></div><div class="ss-writing-analysis" data-writing-analysis hidden></div></div><aside><div class="ss-block"><b>Practice timer</b><p>Custom practice timer — FEI specifies 60 minutes for all 3 writing tasks together, not a fixed time per task.</p><div class="ss-clock" data-lab-clock>20:00</div><div class="ss-row" style="margin-top:9px"><button class="ss-primary ss-mini" data-lab-start>Start</button><button class="ss-secondary ss-mini" data-lab-reset>Reset</button></div></div><div class="ss-block"><b>Self-check before finishing</b><div class="ss-checks" data-writing-checks>${writingChecks(task,key)}</div></div><div class="ss-block"><b>FEI-aligned self-rubric</b><p>Practice reflection only — not an official score.</p>${productionRubricHtml('writing',key)}</div></aside></div>`,modal=>{const ed=$('[data-writing-editor]',modal),status=$('[data-word-status]',modal),bar=$('[data-word-bar]',modal);function update(){const n=wordCount(ed.value),good=n>=bounds[0]&&n<=bounds[1];status.textContent=`${n} words · ${n<bounds[0]?`${bounds[0]-n} short`:n>bounds[1]?`${n-bounds[1]} over`:'within target'}`;status.className='ss-word-status '+(good?'good':'warn');bar.style.width=`${Math.min(100,n/bounds[1]*100)}%`;bar.style.background=n>bounds[1]?'#b8324a':good?'#15825a':'#d99a25';suite.drafts[key]=ed.value;saveSuite()}ed.oninput=update;update();$('[data-save-draft]',modal).onclick=()=>{suite.drafts[key]=ed.value;saveSuite();toast('Draft saved locally')};$('[data-copy-draft]',modal).onclick=()=>navigator.clipboard?.writeText(ed.value);$('[data-clear-draft]',modal).onclick=()=>{if(confirm('Clear this local draft?')){ed.value='';update()}};$$('[data-writing-check]',modal).forEach(x=>x.onchange=()=>{suite.checklists[key]=suite.checklists[key]||{};suite.checklists[key][x.dataset.writingCheck]=x.checked;saveSuite()});const aw=$('[data-analyze-writing]',modal),ao=$('[data-writing-analysis]',modal);if(aw&&ao)aw.onclick=()=>{ao.innerHTML=writingAnalysisHtml(ed.value,task);ao.hidden=false};bindProductionRubric(modal,'writing',key);bindCountdown(modal,20*60)})}
function writingChecks(task,key){const common=['I answered the exact task and audience.','My ideas are clear and logically connected.','I used varied vocabulary and sentence structures.','I checked agreement, verb forms, accents and punctuation.'];const extra=task===3?['I compared BOTH source viewpoints.','I clearly gave and justified my own opinion.']:task===2?['I included experience/details plus comments, opinions or arguments.']:['I described, narrated and/or explained the requested information.'];const all=[...extra,...common],saved=suite.checklists[key]||{};return all.map((x,i)=>`<label><input type="checkbox" data-writing-check="${i}" ${saved[i]?'checked':''}> <span>${esc(x)}</span></label>`).join('')}
