function openSpeakingLab(){openLabModal('Speaking Lab','Real TCF Canada task timings with local microphone practice',`<div class="ss-lab-grid"><div><div class="ss-block"><label><b>Choose task</b></label><select class="ss-select" data-speaking-task style="margin-top:7px"><option value="1">Tâche 1 · Interview · 2:00 · no preparation</option><option value="2">Tâche 2 · Interaction · 5:30 total · 2:00 preparation</option><option value="3">Tâche 3 · Point of view · 4:30 · no preparation</option></select></div><div class="ss-prompt" data-speaking-guide></div><div class="ss-block"><b>Your practice prompt / notes</b><textarea class="ss-textarea" data-speaking-notes placeholder="Paste the current topic or write a few keywords. For Tâche 2, use prep time for question ideas — not a full script."></textarea></div><div class="ss-row"><button class="ss-primary" data-record>🎙 Start recording</button><button class="ss-secondary" data-play disabled>▶ Play</button><button class="ss-secondary" data-download-audio disabled>Save audio</button></div><div data-record-state style="margin-top:10px"></div><audio controls data-recorded-audio style="width:100%;margin-top:10px;display:none"></audio></div><aside><div class="ss-block"><b>Official task clock</b><div class="ss-clock" data-lab-clock>02:00</div><p data-speaking-phase>No preparation for Tâche 1. Start speaking when ready.</p><div class="ss-row"><button class="ss-primary ss-mini" data-lab-start>Start</button><button class="ss-secondary ss-mini" data-lab-reset>Reset</button></div></div><div class="ss-block"><b>Self-evaluation</b><div class="ss-checks"><label><input type="checkbox"> I answered the situation/question directly.</label><label><input type="checkbox"> I kept speaking without long blocking pauses.</label><label><input type="checkbox"> I connected ideas clearly.</label><label><input type="checkbox"> I used precise vocabulary and varied structures.</label><label><input type="checkbox"> My register matched the situation/examiner.</label></div></div><div class="ss-block"><b>FEI-aligned self-rubric</b><p>Practice reflection only — not an official score.</p><div data-speaking-rubric></div></div></aside></div>`,modal=>{const sel=$('[data-speaking-task]',modal),guide=$('[data-speaking-guide]',modal),phase=$('[data-speaking-phase]',modal);function taskSetup(){stopActiveTimer();const n=+sel.value;const sec=n===1?120:n===2?330:270;$('[data-lab-clock]',modal).textContent=formatTime(sec);phase.textContent=n===2?'First 2:00 is preparation; the full task lasts 5:30 including preparation.':'No preparation for this task.';guide.innerHTML=n===1?'<b>Tâche 1:</b> Speak naturally about yourself and respond to the examiner.':n===2?'<b>Tâche 2:</b> You must obtain information in an everyday interaction. Prepare useful questions, then interact.':'<b>Tâche 3:</b> Give a spontaneous, continuous and convincing point of view. Structure: position → reasons/examples → nuance → conclusion.';const rb=$('[data-speaking-rubric]',modal);if(rb){const key=`speaking:t${n}`;rb.innerHTML=productionRubricHtml('speaking',key);bindProductionRubric(rb,'speaking',key)}bindCountdown(modal,sec,n===2?120:null)}sel.onchange=taskSetup;taskSetup();$('[data-record]',modal).onclick=()=>toggleRecording(modal);$('[data-play]',modal).onclick=()=>{const a=$('[data-recorded-audio]',modal);if(a.src)a.play()};$('[data-download-audio]',modal).onclick=()=>downloadRecording(modal)})}
function openLabModal(title,sub,html,onReady){stopActiveTimer();document.body.insertAdjacentHTML('beforeend',`<div class="ss-modal-back"><section class="ss-modal" role="dialog" aria-modal="true"><div class="ss-modal-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="ss-close" data-lab-close aria-label="Close">×</button></div><div class="ss-modal-body">${html}</div></section></div>`);const back=$('.ss-modal-back'),modal=$('.ss-modal',back);$('[data-lab-close]',modal).onclick=()=>closeLab(back);back.addEventListener('click',e=>{if(e.target===back)closeLab(back)});if(onReady)onReady(modal)}
function closeLab(back){stopActiveTimer();stopRecording(true);if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}back?.remove()}
function bindCountdown(root,seconds,prepSeconds=null){let remain=seconds;const clock=$('[data-lab-clock]',root),start=$('[data-lab-start]',root),reset=$('[data-lab-reset]',root),phase=$('[data-speaking-phase]',root);function paint(){if(clock)clock.textContent=formatTime(remain);if(prepSeconds!=null&&phase){const elapsed=seconds-remain;phase.textContent=elapsed<prepSeconds?`Preparation · ${formatTime(prepSeconds-elapsed)} remaining`:`Speaking/interaction · ${formatTime(remain)} remaining`}}function startTimer(){stopActiveTimer();start.textContent='Pause';let running=true;activeTimer=setInterval(()=>{remain--;paint();if(remain<=0){stopActiveTimer();start.textContent='Done';toast('Time is up')}},1000);start.onclick=()=>{if(running){stopActiveTimer();running=false;start.textContent='Resume'}else{running=true;startTimer()}}}start.onclick=startTimer;reset.onclick=()=>{stopActiveTimer();remain=seconds;start.textContent='Start';paint();start.onclick=startTimer};paint()}
function stopActiveTimer(){if(activeTimer){clearInterval(activeTimer);activeTimer=null}}
function formatTime(n){return `${String(Math.max(0,Math.floor(n/60))).padStart(2,'0')}:${String(Math.max(0,n%60)).padStart(2,'0')}`}
async function toggleRecording(modal){const btn=$('[data-record]',modal),state=$('[data-record-state]',modal);if(mediaRecorder&&mediaRecorder.state==='recording'){stopRecording(false);btn.textContent='🎙 Start recording';state.innerHTML='Processing recording…';return}if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){state.innerHTML='<span style="color:#a66513">Microphone recording is unavailable in this browser/file mode. The timer and self-evaluation still work.</span>';return}try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});mediaChunks=[];mediaRecorder=new MediaRecorder(mediaStream);mediaRecorder.ondataavailable=e=>{if(e.data.size)mediaChunks.push(e.data)};mediaRecorder.onstop=()=>{const blob=new Blob(mediaChunks,{type:mediaRecorder.mimeType||'audio/webm'});if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(blob);const audio=$('[data-recorded-audio]',modal);audio.src=objectUrl;audio.style.display='block';$('[data-play]',modal).disabled=false;$('[data-download-audio]',modal).disabled=false;state.innerHTML='Recording ready — listen back and self-evaluate.';mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null};mediaRecorder.start();btn.textContent='⏹ Stop recording';state.innerHTML='<div class="ss-recording"><span class="ss-dot"></span> Recording locally…</div>'}catch(e){state.innerHTML='<span style="color:#a66513">Microphone permission was not granted. You can still use the task timer.</span>'}}
function stopRecording(silent){if(mediaRecorder&&mediaRecorder.state==='recording')try{mediaRecorder.stop()}catch(e){};if(mediaStream){mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null}if(silent){mediaRecorder=null;mediaChunks=[]}}
