function openFocusTimer(){openLabModal('Focus Timer','A simple local study timer — no notifications or internet required',`<div class="ss-block" style="text-align:center;max-width:520px;margin:auto"><div class="ss-clock" data-lab-clock style="font-size:52px">25:00</div><div class="ss-row" style="justify-content:center;margin-top:15px"><button class="ss-primary" data-lab-start>Start</button><button class="ss-secondary" data-lab-reset>Reset</button></div><p>25 minutes is a study preference, not an official TCF timing.</p></div>`,modal=>bindCountdown(modal,25*60))}
function formatSheetHtml(){return `<div class="ss-block"><b>TCF Canada · official structure</b><p><b>Listening:</b> 39 MCQ · 35 min<br><b>Reading:</b> 39 MCQ · 60 min<br><b>Writing:</b> 3 tasks · 60 min total<br><b>Speaking:</b> 3 tasks · 12 min total (2 min preparation occurs in Task 2)</p></div><div class="ss-block"><b>Writing word ranges</b><p>Tâche 1: <b>60–120</b><br>Tâche 2: <b>120–150</b><br>Tâche 3: <b>120–180</b></p></div><div class="ss-block"><b>Speaking task clock</b><p>Tâche 1: <b>2:00</b>, no prep<br>Tâche 2: <b>5:30 total</b>, including <b>2:00 prep</b><br>Tâche 3: <b>4:30</b>, no prep</p></div><p style="font-size:11px;color:var(--muted)">Built from the current France Éducation international TCF Canada format. Your original mock content remains unchanged.</p>`}
function openFormatSheet(){openLabModal('TCF Canada Quick Sheet','Current exam structure used by this Study Hub',formatSheetHtml())}
function buildSearchIndex(){const out=[];(window.TCF_EXAMS||[]).forEach(e=>e.questions.forEach((q,i)=>out.push({kind:'question',examId:e.id,type:e.type,number:e.number,q:i,title:`${e.type==='listening'?'Listening':'Reading'} ${e.number} · Q${i+1}`,text:[q.prompt,q.content,...(q.options||[]).map(o=>o.label),q.explanation].filter(Boolean).join(' ')})));const r=window.TCF_RESOURCES||{};(r.writing||[]).forEach((x,ri)=>(x.subjects||[]).forEach(s=>out.push({kind:'writing',resourceIndex:ri,subject:s.number,title:`Writing · ${x.label} · Sujet ${s.number}`,text:[...(s.prompt||[]),...(s.correction||[])].join(' ')})));(r.speaking||[]).forEach((x,ri)=>out.push({kind:'speaking',resourceIndex:ri,title:`Speaking · ${x.label}`,text:(x.heading||'')+' '+String(x.html||'').replace(/<[^>]+>/g,' ')}));return out}
let searchIndex=null;
function openSearch(){if(!searchIndex)searchIndex=buildSearchIndex();openLabModal('Search your TCF library','Search questions, answers, explanations, writing subjects and speaking lessons',`<input class="ss-input" data-global-search autofocus placeholder="Type a French word, phrase, grammar point or topic…"><div class="ss-search-results" data-search-results><div class="ss-empty">Start typing at least 2 characters.</div></div>`,modal=>{const input=$('[data-global-search]',modal),res=$('[data-search-results]',modal);input.oninput=()=>{const q=input.value.trim().toLowerCase();if(q.length<2){res.innerHTML='<div class="ss-empty">Start typing at least 2 characters.</div>';return}const terms=q.split(/\s+/).filter(Boolean),hits=searchIndex.map(x=>{const t=x.text.toLowerCase(),score=terms.reduce((n,w)=>n+(t.includes(w)?1:0),0);return {...x,score}}).filter(x=>x.score===terms.length).slice(0,40);res.innerHTML=hits.length?hits.map((x,i)=>`<button class="ss-search-result" data-hit="${i}"><b>${esc(x.title)}</b><p>${esc(snippet(x.text,q))}</p></button>`).join(''):'<div class="ss-empty">No matches.</div>';$$('[data-hit]',res).forEach((b,i)=>b.onclick=()=>{const x=hits[i];closeLab($('.ss-modal-back'));if(x.kind==='question')openLearnQuestion(x.examId,x.q);else openResourceResult(x)})};setTimeout(()=>input.focus(),30)})}
function snippet(text,q){const clean=String(text||'').replace(/\s+/g,' ').trim(),i=clean.toLowerCase().indexOf(q.split(/\s+/)[0]);return (i>=0?(i>55?'…':'')+clean.slice(Math.max(0,i-55),i+150):clean.slice(0,200))+(clean.length>200?'…':'')}
function openResourceResult(x){const home=$('[data-home]');if(home)home.click();const type=x.kind==='writing'?'writing':'speaking';setTimeout(()=>{$(`[data-type="${type}"]`)?.click();setTimeout(()=>{$(`[data-resource="${type}"][data-index="${x.resourceIndex}"]`)?.click();if(x.kind==='writing')setTimeout(()=>document.getElementById(`sujet-${x.subject}`)?.scrollIntoView({behavior:'smooth',block:'start'}),80)},40)},40)}
function backupData(){const payload={format:'TCF-Canada-Offline-Backup',version:1,created:new Date().toISOString(),originalProgress:baseProgress(),studySuite:suite};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`TCF-backup-${TODAY()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function restoreData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(p.format!=='TCF-Canada-Offline-Backup')throw new Error('Invalid backup');if(p.originalProgress)localStorage.setItem(BASE_KEY,JSON.stringify(p.originalProgress));if(p.studySuite){suite=p.studySuite;saveSuite()}alert('Backup restored. The page will reload.');location.reload()}catch(e){alert('That file is not a valid TCF Study Hub backup.')}};r.readAsText(file)}
function toast(msg){let t=$('#ss-toast');if(!t){t=document.createElement('div');t.id='ss-toast';t.style.cssText='position:fixed;left:50%;bottom:82px;transform:translateX(-50%);z-index:180;background:#102f2c;color:#fff;padding:10px 14px;border-radius:999px;font-weight:800;font-size:12px;box-shadow:0 10px 25px rgba(0,0,0,.2)';document.body.appendChild(t)}t.textContent=msg;t.style.display='block';clearTimeout(t._timer);t._timer=setTimeout(()=>t.style.display='none',1800)}

/* Mouse-selection translator — Learn/Review only. Translation card stays open until explicitly dismissed. */
let selectedText='',selectedRect=null,translationPinned=false;
document.addEventListener('mouseup',e=>{if(e.button!==0||e.target.closest('#ss-select-pop'))return;setTimeout(()=>handleMouseSelection(e),0)});
function allowedTranslationSelection(sel){if(!sel||sel.isCollapsed||!sel.rangeCount)return false;const range=sel.getRangeAt(0),node=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;if(!node)return false;return !!(node.closest('[data-learning]')||node.closest('[data-review]'))}
function handleMouseSelection(){const pop=$('#ss-select-pop');if(!pop)return;const sel=window.getSelection();if(!allowedTranslationSelection(sel)){if(!translationPinned)hideSelectionPop(true);return}const text=sel.toString().replace(/\s+/g,' ').trim();if(!text||text.length<2){if(!translationPinned)hideSelectionPop(true);return}translationPinned=false;selectedText=text;const r=sel.getRangeAt(0).getBoundingClientRect();selectedRect=r;positionSelectionPop(r);pop.classList.add('visible');pop.innerHTML='<button class="ss-select-trigger" type="button" data-translate-selection>🌐 Translate to English</button>';$('[data-translate-selection]',pop).onclick=e=>{e.preventDefault();e.stopPropagation();translationPinned=true;translateSelection(text)}}
function positionSelectionPop(r){const pop=$('#ss-select-pop');if(!pop)return;const width=Math.min(410,window.innerWidth-28),left=Math.min(window.innerWidth-width-14,Math.max(14,r.left+r.width/2-90)),top=Math.min(window.innerHeight-80,Math.max(14,r.bottom+8));pop.style.left=`${left}px`;pop.style.top=`${top}px`}
function hideSelectionPop(force=false){if(translationPinned&&!force)return;const p=$('#ss-select-pop');translationPinned=false;if(p){p.classList.remove('visible');p.innerHTML=''}}
document.addEventListener('mousedown',e=>{if(e.target.closest('#ss-select-pop'))return;if(translationPinned)hideSelectionPop(true)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideSelectionPop(true)});
window.addEventListener('scroll',()=>{if(!translationPinned)hideSelectionPop(true)},{passive:true});
async function translateSelection(text){const pop=$('#ss-select-pop');if(!pop)return;translationPinned=true;const cached=suite.translations[text];pop.classList.add('visible');pop.innerHTML=`<div class="ss-translation-card"><button class="ss-trans-close" data-close-translation aria-label="Close translation">×</button><div class="ss-origin">${esc(text)}</div><div class="ss-translated">${cached?esc(cached):'<span class="ss-loading"></span> Translating…'}</div>${cached?translationActions(text,cached):''}</div>`;bindTranslationClose(pop);if(cached)return;try{if(new TextEncoder().encode(text).length>480)throw new Error('Select a shorter phrase (under about 450 characters).');const url=`https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=fr|en&mt=1`;const res=await fetch(url,{method:'GET',headers:{Accept:'application/json'}});if(!res.ok)throw new Error('Translation service unavailable');const data=await res.json(),tr=data?.responseData?.translatedText;if(!tr)throw new Error('No translation returned');suite.translations[text]=tr;if(Object.keys(suite.translations).length>300){const k=Object.keys(suite.translations)[0];delete suite.translations[k]}saveSuite();pop.innerHTML=`<div class="ss-translation-card"><button class="ss-trans-close" data-close-translation aria-label="Close translation">×</button><div class="ss-origin">${esc(text)}</div><div class="ss-translated">${esc(tr)}</div>${translationActions(text,tr)}</div>`;bindTranslationClose(pop)}catch(err){pop.innerHTML=`<div class="ss-translation-card"><button class="ss-trans-close" data-close-translation aria-label="Close translation">×</button><div class="ss-origin">${esc(text)}</div><div class="ss-translated" style="font-weight:600;color:#8a5b18">${esc(err.message||'Could not translate. You may be offline.')}</div><div class="ss-trans-note">The card will stay open. Check your internet connection and select the phrase again to retry.</div></div>`;bindTranslationClose(pop)}}
function bindTranslationClose(pop){const b=$('[data-close-translation]',pop);if(b)b.onclick=e=>{e.preventDefault();e.stopPropagation();hideSelectionPop(true)}}
function translationActions(fr,en){const c=currentExamContext(),listening=c?.type==='listening'&&(currentMode()==='learning'||currentMode()==='review');return `<div class="ss-translation-actions">${listening?'<button data-play-source-audio>🎧 Original audio</button>':'<button data-speak-fr>🔊 French</button>'}<button data-copy-en>Copy English</button><button data-save-phrase>＋ Save phrase</button></div><div class="ss-trans-note">${listening?'Listening pronunciation comes from the original mock recording — not a computer voice.':'Study helper translation. Machine translation can be imperfect; use context for exam meaning.'}</div>`}
document.addEventListener('click',e=>{const sf=e.target.closest('[data-speak-fr]');if(sf){e.preventDefault();if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(selectedText);u.lang='fr-FR';u.rate=.9;speechSynthesis.speak(u)}}const real=e.target.closest('[data-play-source-audio]');if(real){e.preventDefault();const c=currentExamContext();if(c?.type==='listening')playOriginalQuestionAudio(c.exam,c.q,1);else toast('Original listening audio unavailable here')}const cp=e.target.closest('[data-copy-en]');if(cp){const tr=$('.ss-translated',$('#ss-select-pop'))?.textContent||'';navigator.clipboard?.writeText(tr);toast('Translation copied')}const sv=e.target.closest('[data-save-phrase]');if(sv){const tr=$('.ss-translated',$('#ss-select-pop'))?.textContent||'';savePhrase(selectedText,tr);toast('Phrase saved to flashcards')}});

/* Advanced Coach v4: active recall, error diagnosis, dictation and adaptive practice. */
const REASONS=['vocab','grammar','didnt-hear','misread','distractor','inference','rushed','guessed'];
function reasonLabel(r){return ({vocab:'Vocabulary gap',grammar:'Grammar / structure', 'didnt-hear':'Did not hear it',misread:'Misread / missed detail',distractor:'Distractor trap',inference:'Inference / logic',rushed:'Rushed / timing',guessed:'Guessed'})[r]||r}
function mistakeReasonStats(){const m=suite.mistakeReasons||{},counts={};Object.values(m).flat().forEach(r=>counts[r]=(counts[r]||0)+1);return Object.entries(counts).map(([reason,count])=>({reason,count})).sort((a,b)=>b.count-a.count)}
function allAttempts(){const p=baseProgress(),out=[];(window.TCF_EXAMS||[]).forEach(e=>(p[e.id]?.attempts||[]).forEach(a=>out.push({...a,type:e.type,number:e.number,id:e.id})));return out.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')))}
function readinessSignals(){const a=allAttempts(),recent=a.slice(-5),avg=recent.length?Math.round(recent.reduce((n,x)=>n+(x.score||0)/39*100,0)/recent.length):null;const due=dueItems().length,m=frequentMistakes().length;if(!a.length)return {recentAvg:null,message:'Start with a diagnostic mock',detail:'Complete one listening or reading mock. The coach will then adapt to your results.'};const danger=highConfidenceMisses().length;if(danger>=3)return {recentAvg:avg,message:'Fix confident mistakes first',detail:`You have ${danger} high-confidence misses. These are more dangerous than guesses because they can reflect a false rule or misunderstanding.`};if(due>8)return {recentAvg:avg,message:'Clear your review debt first',detail:`You have ${due} due review items. Fix old errors before adding lots of new questions.`};if(m>20)return {recentAvg:avg,message:'Turn repeated errors into strengths',detail:`${m} questions have been missed before. Use Smart drill and tag the cause of each miss.`};if(avg!=null&&avg>=80)return {recentAvg:avg,message:'Shift toward exam simulation',detail:'Your recent raw accuracy is strong. Keep weak-point review, but increase full timed practice and speaking/writing production.'};return {recentAvg:avg,message:'Build accuracy before speed',detail:'Use Learn/Review mode deliberately: explain each error, save useful phrases, then retest it after a delay.'}}
function daysUntilExam(){if(!suite.examDate)return null;const a=new Date(TODAY()+'T12:00:00'),b=new Date(suite.examDate+'T12:00:00');if(Number.isNaN(b.getTime()))return null;return Math.round((b-a)/86400000)}
function questionKey(c){return c?`${c.exam.id}:q${c.q+1}`:''}
function questionWasWrong(){const mode=currentMode();if(mode==='learning')return !!$('.feedback.bad');if(mode==='review'){const t=$('[data-review] .question-count')?.textContent||'';return /Incorrect|Skipped/i.test(t)}return false}
function questionRevealed(){return currentMode()==='review'||!!$('.feedback')}
function enhanceQuestionCoach(){const mode=currentMode();if(mode!=='learning'&&mode!=='review')return;const c=currentExamContext();if(!c||!questionRevealed())return;const host=$('[data-learning]')||$('[data-review]');if(!host||$('.ss-diagnose',host))return;const key=questionKey(c),wrong=questionWasWrong(),savedReasons=(suite.mistakeReasons||{})[key]||[],conf=(suite.confidence||{})[key]||'';const panel=document.createElement('div');panel.className='ss-diagnose';panel.innerHTML=`<div class="ss-diagnose-head"><div><b>${wrong?'🧩 Diagnose this miss':'🎯 Calibrate your confidence'}</b><small>${wrong?'Tag the real reason so the coach can find your pattern.':'Record how sure you were before checking the answer.'}</small></div></div><div class="ss-confidence"><span>Confidence:</span>${['guess','unsure','sure'].map(x=>`<button class="${conf===x?'active':''}" data-conf="${x}">${x==='guess'?'🎲 Guess':x==='unsure'?'🤔 Unsure':'✅ Sure'}</button>`).join('')}</div>${wrong?`<div class="ss-reason-tags">${REASONS.map(r=>`<button class="${savedReasons.includes(r)?'active':''}" data-reason="${r}">${esc(reasonLabel(r))}</button>`).join('')}</div>`:''}`;const explain=$('.explain:last-of-type',host)||$('.feedback',host);(explain||host.lastElementChild)?.insertAdjacentElement('afterend',panel);$$('[data-conf]',panel).forEach(b=>b.onclick=()=>{suite.confidence=suite.confidence||{};suite.confidence[key]=b.dataset.conf;saveSuite();$$('[data-conf]',panel).forEach(x=>x.classList.toggle('active',x===b))});$$('[data-reason]',panel).forEach(b=>b.onclick=()=>{suite.mistakeReasons=suite.mistakeReasons||{};let arr=suite.mistakeReasons[key]||[];arr=arr.includes(b.dataset.reason)?arr.filter(x=>x!==b.dataset.reason):[...arr,b.dataset.reason];suite.mistakeReasons[key]=arr;saveSuite();b.classList.toggle('active');refreshCommandCenter()});const qtools=document.createElement('div');qtools.className='ss-inline-coach-tools';qtools.innerHTML=`<button class="ss-secondary ss-mini" data-q-blind>🧠 Blind retest</button><button class="ss-secondary ss-mini" data-q-traps>🪤 Distractors</button>${c.type==='listening'?'<button class="ss-secondary ss-mini" data-q-dict>🎧 Dictation</button><button class="ss-secondary ss-mini" data-q-cloze>🧩 Cloze</button>':''}`;panel.appendChild(qtools);$('[data-q-blind]',qtools).onclick=()=>openBlindRetry(c.exam.id,c.q);$('[data-q-traps]',qtools).onclick=()=>openDistractorLab(c.exam.id,c.q);if(c.type==='listening'){$('[data-q-dict]',qtools).onclick=()=>openDictation(c.exam.id,c.q);$('[data-q-cloze]',qtools).onclick=()=>openClozeDrill(c.exam.id,c.q)}}
function savePhrase(fr,en){if(!fr||!en)return;suite.phrasebook=suite.phrasebook||[];const existing=suite.phrasebook.find(x=>x.fr.toLowerCase()===fr.toLowerCase());if(existing){existing.en=en;existing.saved=TODAY();return saveSuite()}suite.phrasebook.push({id:'p'+Date.now(),fr,en,saved:TODAY(),due:TODAY(),interval:0,ease:0,context:contextKey()});saveSuite()}
function phraseDue(){const t=TODAY();return (suite.phrasebook||[]).filter(x=>(x.due||x.saved||t)<=t)}
function gradePhrase(id,grade){const x=(suite.phrasebook||[]).find(v=>v.id===id);if(!x)return;const seq=grade==='again'?[1,1,1]:grade==='good'?[1,3,7,14,30]:[3,7,14,30,60];x.ease=(x.ease||0)+(grade==='again'?0:1);const idx=Math.min(x.ease,seq.length-1);x.interval=seq[idx];x.due=addDays(x.interval);saveSuite()}
function openPhrasebook(){const all=suite.phrasebook||[],due=phraseDue();if(!all.length){openLabModal('Phrasebook','Active recall from phrases you save while translating','<div class="ss-empty">Highlight French in Learn/Review mode → Translate → <b>Save phrase</b>. It will appear here as a flashcard.</div>');return}const cards=due.length?due:all.slice(-20);let i=0;openLabModal('Phrasebook flashcards',`${due.length} due · ${all.length} saved`,`<div data-flash></div>`,modal=>{const box=$('[data-flash]',modal);function draw(){const x=cards[i%cards.length];box.innerHTML=`<div class="ss-flash"><small>FRENCH → recall the meaning</small><div class="ss-flash-fr">${esc(x.fr)}</div><button class="ss-primary" data-reveal-flash>Reveal English</button><div class="ss-flash-en" data-flash-en hidden>${esc(x.en)}</div><div class="ss-flash-grade" data-flash-grade hidden><button data-grade="again">Again</button><button data-grade="good">Good</button><button data-grade="easy">Easy</button></div><div class="ss-row" style="margin-top:12px"><button class="ss-secondary ss-mini" data-speak-card>🔊 French</button><button class="ss-danger ss-mini" data-delete-card>Delete</button></div></div>`;$('[data-reveal-flash]',box).onclick=()=>{$('[data-flash-en]',box).hidden=false;$('[data-flash-grade]',box).hidden=false;$('[data-reveal-flash]',box).hidden=true};$$('[data-grade]',box).forEach(b=>b.onclick=()=>{gradePhrase(x.id,b.dataset.grade);i++;draw()});$('[data-speak-card]',box).onclick=()=>speakFrench(x.fr,.9);$('[data-delete-card]',box).onclick=()=>{suite.phrasebook=suite.phrasebook.filter(v=>v.id!==x.id);saveSuite();cards.splice(i%cards.length,1);if(!cards.length){box.innerHTML='<div class="ss-empty">No cards left in this session.</div>';return}i=i%cards.length;draw()}}draw()})}
function smartDrillItems(){const out=[],seen=new Set();function add(x,why){const key=`${x.examId||x.id}:q${x.q+1}`;if(seen.has(key))return;const e=(window.TCF_EXAMS||[]).find(v=>v.id===(x.examId||x.id));if(!e)return;seen.add(key);out.push({examId:e.id,type:e.type,number:e.number,q:x.q,why})}(dueItems()).forEach(x=>add(x,'Due spaced review'));frequentMistakes().forEach(x=>add(x,`Missed ${x.misses}×`));const weak=scoreStats().weakest.toLowerCase();if(weak==='listening'||weak==='reading'){(window.TCF_EXAMS||[]).filter(e=>e.type===weak).forEach(e=>e.questions.forEach((q,i)=>{if(out.length<15)add({examId:e.id,q:i},'Weak-skill practice')}))}return out.slice(0,15)}
function openSmartDrill(){const items=smartDrillItems();openLabModal('Smart drill','Prioritized from your own history — not a random worksheet',items.length?`<div class="ss-smart-list">${items.map((x,i)=>`<button data-smart-i="${i}"><span>${i+1}</span><b>${x.type==='listening'?'Listening':'Reading'} ${x.number} · Q${x.q+1}</b><small>${esc(x.why)}</small></button>`).join('')}</div>`:'<div class="ss-empty">Complete a mock or queue some questions for review first.</div>',modal=>$$('[data-smart-i]',modal).forEach(b=>b.onclick=()=>{const x=items[+b.dataset.smartI];closeLab($('.ss-modal-back'));closeDrawer();openLearnQuestion(x.examId,x.q)}))}
function openErrorJournal(){const stats=mistakeReasonStats(),entries=Object.entries(suite.mistakeReasons||{}).filter(([,v])=>v?.length);openLabModal('Error journal','Find the cause behind your wrong answers',`<div class="ss-coach-grid"><div class="ss-block"><b>${entries.length}</b><p>tagged questions</p></div><div class="ss-block"><b>${stats[0]?esc(reasonLabel(stats[0].reason)):'—'}</b><p>most common cause</p></div></div><div class="ss-reason-bars">${stats.length?stats.map(x=>`<div><span>${esc(reasonLabel(x.reason))}</span><i><b style="width:${Math.max(8,Math.round(x.count/stats[0].count*100))}%"></b></i><strong>${x.count}</strong></div>`).join(''):'<div class="ss-empty">No mistake causes tagged yet.</div>'}</div><h3 style="margin-top:18px">Tagged questions</h3><div class="ss-list">${entries.slice(-30).reverse().map(([key,reasons])=>{const m=key.match(/(.+):q(\d+)/),e=(window.TCF_EXAMS||[]).find(v=>v.id===m?.[1]),q=(+(m?.[2]||1))-1;return `<div class="ss-list-item"><div class="ss-grow"><b>${e?(e.type==='listening'?'Listening':'Reading')+' '+e.number+' · Q'+(q+1):esc(key)}</b><small>${reasons.map(reasonLabel).join(' · ')}</small></div>${e?`<button class="ss-secondary ss-mini" data-error-open="${esc(e.id)}" data-error-q="${q}">Study</button>`:''}</div>`}).join('')||'<div class="ss-empty">Nothing yet.</div>'}</div>`,modal=>$$('[data-error-open]',modal).forEach(b=>b.onclick=()=>{closeLab($('.ss-modal-back'));closeDrawer();openLearnQuestion(b.dataset.errorOpen,+b.dataset.errorQ)}))}
function localTranscript(q){let t=String(q?.explanation||'').replace(/\u00a0/g,' ').trim(),m=t.match(/transcription\s*:\s*/i);if(m)t=t.slice((m.index||0)+m[0].length);else t=t.replace(/^\s*(?:Explication|Explanation)\s*:\s*/i,'');return t.replace(/\s+/g,' ').trim()}
function speakFrench(text,rate=.9){if(!('speechSynthesis'in window)||!text)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';u.rate=rate;speechSynthesis.speak(u)}
function playOriginalQuestionAudio(exam,qIndex,rate=1,opts={}){const api=window.TCF_REAL_AUDIO;if(!api?.available?.(exam,qIndex)){toast('Original question audio segment unavailable');return false}api.play(exam,qIndex,{rate,loop:!!opts.loop,restart:opts.restart!==false,toggle:false});return true}
function openDictation(examId,qIndex){const e=(window.TCF_EXAMS||[]).find(x=>x.id===examId),q=e?.questions?.[qIndex],tr=localTranscript(q);if(!e||!q||!tr){toast('No usable transcript for this question');return}openLabModal(`Dictation · Listening ${e.number} Q${qIndex+1}`,'Uses the ORIGINAL recorded question audio. Type what you hear before revealing the transcript.',`<div class="ss-block ss-real-audio-lab"><b>🎧 Original TCF audio</b><div class="ss-row" style="flex-wrap:wrap;margin-top:9px"><button class="ss-primary" data-dict-play>▶ 1.00×</button><button class="ss-secondary" data-dict-slow>🐢 0.75×</button><button class="ss-secondary" data-dict-shadow>🗣 Shadow 0.90×</button><button class="ss-secondary" data-dict-loop>🔁 Loop</button></div><small>All buttons use the real MP3 segment from your listening mock — no text-to-speech.</small></div><textarea class="ss-editor ss-dictation" data-dict-text placeholder="Type exactly what you hear in French…"></textarea><div class="ss-row" style="margin-top:10px;flex-wrap:wrap"><button class="ss-primary" data-dict-reveal>Reveal transcript</button><button class="ss-secondary" data-dict-clear>Clear</button></div><div class="ss-prompt ss-dict-transcript" data-dict-transcript hidden style="margin-top:12px">${esc(tr)}</div><p class="ss-coach-tip"><b>Method:</b> 1× for exam-like listening → 0.75× only to diagnose missed sounds → 0.90× shadowing for rhythm and pronunciation.</p>`,modal=>{$('[data-dict-play]',modal).onclick=()=>playOriginalQuestionAudio(e,qIndex,1);$('[data-dict-slow]',modal).onclick=()=>playOriginalQuestionAudio(e,qIndex,.75);$('[data-dict-shadow]',modal).onclick=()=>playOriginalQuestionAudio(e,qIndex,.9);$('[data-dict-loop]',modal).onclick=()=>playOriginalQuestionAudio(e,qIndex,1,{loop:true});$('[data-dict-reveal]',modal).onclick=()=>{const x=$('[data-dict-transcript]',modal);x.hidden=false};$('[data-dict-clear]',modal).onclick=()=>{$('[data-dict-text]',modal).value=''}})};
function currentQuestionSnapshot(){const c=currentExamContext();if(!c)return null;return {exam:c.exam,qIndex:c.q,q:c.exam.questions[c.q]}}
function highConfidenceMisses(){const p=baseProgress(),out=[];Object.entries(suite.confidence||{}).forEach(([key,conf])=>{if(conf!=='sure')return;const m=key.match(/(.+):q(\d+)/);if(!m)return;const e=(window.TCF_EXAMS||[]).find(x=>x.id===m[1]),q=+m[2]-1;if(!e||q<0)return;const attempts=p[e.id]?.attempts||[];let misses=0;attempts.forEach(a=>{const ci=e.questions[q].options.findIndex(o=>o.correct);if(a.answers?.[q]==null||a.answers?.[q]!==ci)misses++});if(misses)out.push({examId:e.id,type:e.type,number:e.number,q,misses})});return out.sort((a,b)=>b.misses-a.misses)}
function openNclcTargetMap(){const target=Math.max(7,Math.min(10,+suite.targetNclc||7));openLabModal('Official TCF Canada → NCLC map','IRCC score ranges — use these as your target, not raw mock percentage',`<div class="ss-nclc-table"><div class="ss-nclc-row ss-head"><b>NCLC</b><b>Listening</b><b>Reading</b><b>Speaking</b><b>Writing</b></div>${[7,8,9,10].map(n=>`<div class="ss-nclc-row ${n===target?'target':''}"><strong>${n}</strong><span>${NCLC_TCF[n].listening}</span><span>${NCLC_TCF[n].reading}</span><span>${NCLC_TCF[n].speaking}</span><span>${NCLC_TCF[n].writing}</span></div>`).join('')}</div><div class="ss-coach-tip"><b>Your selected target: NCLC ${target}.</b> This table uses official IRCC TCF Canada equivalencies. Your site’s mock percentages and weighted estimates are practice indicators, not official FEI scores.</div><div class="ss-block"><b>Important scoring fact</b><p>For listening and reading, FEI says only correct answers count; wrong answers receive 0. Official scores are psychometrically weighted, so raw accuracy cannot be converted exactly by a simple percentage.</p></div>`)}
function questionBodyHtml(e,qIndex,showCorrect=false,chosen=null){const q=e.questions[qIndex],ci=q.options.findIndex(o=>o.correct);return `<div class="ss-prompt"><b>${e.type==='listening'?'Listening':'Reading'} ${e.number} · Q${qIndex+1}</b><br>${esc(q.prompt||'Choose the correct answer.')}</div>${q.content?`<div class="ss-retest-content">${esc(q.content)}</div>`:''}${(q.images||[]).map(x=>`<img class="ss-retest-image" src="${esc(x)}" alt="Question illustration">`).join('')}<div class="ss-retest-options">${q.options.map((o,i)=>`<button data-retest-answer="${i}" class="${showCorrect&&i===ci?'correct':''} ${showCorrect&&chosen===i&&i!==ci?'wrong':''}"><span>${String.fromCharCode(65+i)}</span><b>${esc(o.label)}</b></button>`).join('')}</div>`}
function openBlindRetry(examId,qIndex){const e=(window.TCF_EXAMS||[]).find(x=>x.id===examId),q=e?.questions?.[qIndex];if(!e||!q){toast('Question not found');return}let selected=null,revealed=false;openLabModal(`Blind retest · ${e.type==='listening'?'Listening':'Reading'} ${e.number} Q${qIndex+1}`,'Old answers and explanations are hidden until you commit again',`<div data-retest-host>${questionBodyHtml(e,qIndex)}</div><div class="ss-row" style="margin-top:12px"><button class="ss-primary" data-retest-check disabled>Check answer</button><button class="ss-secondary" data-retest-audio ${e.type==='listening'?'':'hidden'}>🎧 Original audio once</button></div><div data-retest-result></div>`,modal=>{const host=$('[data-retest-host]',modal),check=$('[data-retest-check]',modal),result=$('[data-retest-result]',modal),audio=$('[data-retest-audio]',modal);$$('[data-retest-answer]',host).forEach(b=>b.onclick=()=>{if(revealed)return;selected=+b.dataset.retestAnswer;$$('[data-retest-answer]',host).forEach(x=>x.classList.toggle('selected',x===b));check.disabled=false});if(audio&&!audio.hidden){let used=false;audio.onclick=()=>{if(used){toast('One-play challenge: replay locked');return}used=true;audio.disabled=true;playOriginalQuestionAudio(e,qIndex,1)}}check.onclick=()=>{if(selected==null||revealed)return;revealed=true;const ci=q.options.findIndex(o=>o.correct),ok=selected===ci;host.innerHTML=questionBodyHtml(e,qIndex,true,selected);result.innerHTML=`<div class="ss-retest-result ${ok?'good':'bad'}"><b>${ok?'✅ Correct on cold retry':'❌ Still missed on cold retry'}</b><p>${ok?'Good — delayed retrieval is stronger evidence than rereading.':'Do not immediately memorize the letter. Explain why your choice failed, then use Distractor Lab.'}</p></div><div class="ss-explanation-fold"><details><summary>Reveal original explanation / transcription</summary><div>${esc(q.explanation||'No explanation provided.')}</div></details></div>`;suite.blindRetries=suite.blindRetries||[];suite.blindRetries.push({examId:e.id,q:qIndex,correct:ok,date:new Date().toISOString()});suite.blindRetries=suite.blindRetries.slice(-300);saveSuite();check.disabled=true}})}
function openBlindRetryChooser(){const c=currentQuestionSnapshot();if(c){openBlindRetry(c.exam.id,c.qIndex);return}const d=dueItems()[0],m=frequentMistakes()[0],x=d?{examId:d.examId,q:d.q}:m?{examId:m.id,q:m.q}:null;if(x)openBlindRetry(x.examId,x.q);else toast('Complete or queue some questions first')}
function openDistractorLab(examId,qIndex){const e=(window.TCF_EXAMS||[]).find(x=>x.id===examId),q=e?.questions?.[qIndex];if(!e||!q)return;const ci=q.options.findIndex(o=>o.correct),baseKey=`${e.id}:q${qIndex+1}`;suite.trapNotes=suite.trapNotes||{};openLabModal(`Distractor Lab · Q${qIndex+1}`,'Train the difference between “plausible” and “supported by the source”',`<div class="ss-prompt">${esc(q.prompt||'Choose the correct answer.')}</div>${q.content?`<div class="ss-retest-content">${esc(q.content)}</div>`:''}<div class="ss-trap-list">${q.options.map((o,i)=>`<div class="ss-trap-option ${i===ci?'correct':''}"><div class="ss-trap-answer"><span>${String.fromCharCode(65+i)}</span><b>${esc(o.label)}</b>${i===ci?'<em>Correct</em>':''}</div>${i!==ci?`<div class="ss-trap-tags">${TRAP_TYPES.map(([k,label])=>`<button data-trap="${k}" data-trap-option="${i}" class="${suite.trapNotes[baseKey+':'+i]===k?'active':''}">${esc(label)}</button>`).join('')}</div>`:`<p>Find the exact idea in the source that makes this option better than the others.</p>`}</div>`).join('')}</div><div class="ss-coach-tip"><b>Rule:</b> a distractor can contain true words from the audio/text and still be wrong. Choose the option that answers the exact question, not the one that merely sounds familiar.</div>`,modal=>$$('[data-trap]',modal).forEach(b=>b.onclick=()=>{const k=baseKey+':'+b.dataset.trapOption;suite.trapNotes[k]=b.dataset.trap;saveSuite();$$(`[data-trap-option="${b.dataset.trapOption}"]`,modal).forEach(x=>x.classList.toggle('active',x===b));toast('Trap type saved')}))}
function openDistractorChooser(){const c=currentQuestionSnapshot();if(c){openDistractorLab(c.exam.id,c.qIndex);return}const m=frequentMistakes()[0];if(m)openDistractorLab(m.id,m.q);else toast('Open a Learn/Review question or complete a mock first')}
function clozeWords(text){const stop=new Set('avec dans pour mais donc alors comme parce cette celui elle elles nous vous ils sont était être avoir fait faire plus moins très tout tous toute toutes entre après avant quand dont quoi lequel laquelle aux des les une un le la du de et ou en sur sous par sans au ce cet ces sa son ses leur leurs que qui ne pas se il je tu on y'.split(/\s+/));const words=String(text||'').split(/(\s+)/),candidates=[];words.forEach((w,i)=>{const clean=w.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zà-ÿ'-]/g,'');if(clean.length>=5&&!stop.has(clean))candidates.push(i)});const want=Math.min(12,Math.max(4,Math.round(candidates.length*.28)));const chosen=new Set(candidates.filter((_,j)=>j%Math.max(1,Math.floor(candidates.length/want))===0).slice(0,want));return {words,chosen}}
function openClozeDrill(examId,qIndex){const e=(window.TCF_EXAMS||[]).find(x=>x.id===examId),q=e?.questions?.[qIndex],text=localTranscript(q);if(!e||!q||!text){toast('No usable transcript for this question');return}const {words,chosen}=clozeWords(text);openLabModal(`Cloze recall · Listening ${e.number} Q${qIndex+1}`,'Recall missing words from meaning + grammar before revealing them',`<div class="ss-row" style="margin-bottom:10px"><button class="ss-primary" data-cloze-listen>🔊 Listen once</button><button class="ss-secondary" data-cloze-reveal>Reveal all</button><button class="ss-secondary" data-cloze-reset>Reset</button></div><div class="ss-cloze-text" data-cloze-text>${words.map((w,i)=>chosen.has(i)?`<button data-cloze-word="${i}" data-word="${esc(w)}">________</button>`:esc(w)).join('')}</div><p class="ss-coach-tip">Click a blank only after you have tried to retrieve the word. This trains sound recognition, grammar prediction and spelling together.</p>`,modal=>{let used=false;const drawReset=()=>$$('[data-cloze-word]',modal).forEach(b=>{b.textContent='________';b.classList.remove('revealed')});$('[data-cloze-listen]',modal).onclick=()=>{if(used){toast('One-play challenge: reset to listen again');return}used=true;playOriginalQuestionAudio(e,qIndex,1)};$$('[data-cloze-word]',modal).forEach(b=>b.onclick=()=>{b.textContent=b.dataset.word;b.classList.add('revealed')});$('[data-cloze-reveal]',modal).onclick=()=>$$('[data-cloze-word]',modal).forEach(b=>{b.textContent=b.dataset.word;b.classList.add('revealed')});$('[data-cloze-reset]',modal).onclick=()=>{used=false;drawReset()}})}
function openClozeChooser(){const c=currentQuestionSnapshot();if(c?.exam.type==='listening'){openClozeDrill(c.exam.id,c.qIndex);return}const m=frequentMistakes().find(x=>x.type==='listening'),e=m?(window.TCF_EXAMS||[]).find(x=>x.id===m.id):(window.TCF_EXAMS||[]).find(x=>x.type==='listening');if(e)openClozeDrill(e.id,m?.q||0);else toast('No listening content found')}
function productionRubricHtml(kind,key){const old=(suite.productionRubrics||{})[key]||{};const rows=kind==='speaking'?[['linguistic','Linguistic','Vocabulary, grammar, ease, pronunciation and overall fluency'],['pragmatic','Pragmatic','Interaction, structure, coherence/cohesion and development'],['sociolinguistic','Sociolinguistic','Appropriateness to the communication situation']]:[['linguistic','Linguistic','Vocabulary range, grammar, spelling and sentence elaboration'],['pragmatic','Pragmatic','Coherence/cohesion and development of the topic'],['sociolinguistic','Sociolinguistic','Appropriateness to the communication situation']];return `<div class="ss-rubric">${rows.map(([k,label,desc])=>`<label><div><b>${label}</b><small>${desc}</small></div><input type="range" min="1" max="5" step="1" value="${old[k]||3}" data-rubric="${k}"><output>${old[k]||3}/5</output></label>`).join('')}<small class="ss-rubric-note">1 = major difficulty · 3 = developing · 5 = consistently strong. This is your self-reflection scale, not FEI’s official scoring scale.</small></div>`}
function bindProductionRubric(root,kind,key){$$('[data-rubric]',root).forEach(r=>{r.oninput=()=>{const out=r.parentElement.querySelector('output');if(out)out.textContent=r.value+'/5';suite.productionRubrics=suite.productionRubrics||{};suite.productionRubrics[key]=suite.productionRubrics[key]||{kind};suite.productionRubrics[key][r.dataset.rubric]=+r.value;suite.productionRubrics[key].updated=new Date().toISOString();saveSuite()}})}
function writingAnalysisHtml(text,task){const wc=wordCount(text),sent=(String(text).match(/[.!?]+(?=\s|$)/g)||[]).length,paras=String(text).split(/\n\s*\n/).filter(x=>x.trim()).length;const connectors=['d’abord','tout d’abord','ensuite','de plus','en outre','cependant','pourtant','en revanche','par conséquent','donc','ainsi','par exemple','en effet','puisque','parce que','bien que','même si','à mon avis','selon moi','en conclusion','pour conclure'];const low=String(text).toLowerCase(),found=connectors.filter(c=>low.includes(c));const tokens=(low.normalize('NFD').replace(/[\u0300-\u036f]/g,'').match(/[a-z'-]{4,}/g)||[]),stop=new Set('avec dans pour mais donc alors comme parce cette celui elle elles nous vous ils sont etait etre avoir fait faire plus moins tres tout tous toute toutes entre apres avant quand dont quoi lequel laquelle aux des les une un leur leurs que qui sans cela cette aussi vous nous votre notre'.split(/\s+/)),counts={};tokens.filter(w=>!stop.has(w)).forEach(w=>counts[w]=(counts[w]||0)+1);const repeats=Object.entries(counts).filter(([,n])=>n>=4).sort((a,b)=>b[1]-a[1]).slice(0,5);const bounds=writingBounds(task),range=wc>=bounds[0]&&wc<=bounds[1];return `<div class="ss-analysis-grid"><div><b>${wc}</b><span>words</span></div><div><b>${sent}</b><span>sentences</span></div><div><b>${paras}</b><span>paragraphs</span></div><div><b>${found.length}</b><span>connector types</span></div></div><div class="ss-analysis-checks"><p class="${range?'good':'warn'}"><b>${range?'✓':'!'} Word range:</b> ${bounds[0]}–${bounds[1]} expected for Tâche ${task}.</p><p><b>Cohesion signals found:</b> ${found.length?found.map(esc).join(' · '):'none from the built-in connector list — check whether your ideas are clearly linked.'}</p><p><b>Repeated content words:</b> ${repeats.length?repeats.map(([w,n])=>`${esc(w)} ×${n}`).join(' · '):'no obvious heavy repetition detected.'}</p><p><b>Reminder:</b> this local analyzer cannot judge grammar correctness, whether you are on-topic, or whether your argument is convincing. Use the FEI-aligned rubric beside it.</p></div>`}
function weeklyDates(n=7){const out=[];const d=new Date();for(let i=n-1;i>=0;i--){const x=new Date(d);x.setDate(d.getDate()-i);out.push(x.toISOString().slice(0,10))}return out}
function openWeeklyReport(){const dates=weeklyDates(7),acts=dates.map(d=>({d,...(suite.activity[d]||{questions:0,actions:0,minutes:0})})),questions=acts.reduce((n,x)=>n+(x.questions||0),0),activeDays=acts.filter(x=>(x.actions||0)>0).length,attempts=allAttempts().filter(a=>{const t=new Date(a.date||0);return Number.isFinite(t.getTime())&&t>=new Date(Date.now()-7*86400000)}),avg=attempts.length?Math.round(attempts.reduce((n,a)=>n+(a.score||0)/39*100,0)/attempts.length):null,errs=frequentMistakes().slice(0,5),danger=highConfidenceMisses(),retries=(suite.blindRetries||[]).filter(x=>new Date(x.date)>=new Date(Date.now()-7*86400000)),retryRate=retries.length?Math.round(retries.filter(x=>x.correct).length/retries.length*100):null,maxQ=Math.max(1,...acts.map(x=>x.questions||0));openLabModal('7-day study report','Use trends to decide what to repair next week',`<div class="ss-report-metrics"><div><b>${activeDays}/7</b><span>active days</span></div><div><b>${questions}</b><span>question actions</span></div><div><b>${avg==null?'—':avg+'%'}</b><span>mock raw avg</span></div><div><b>${retryRate==null?'—':retryRate+'%'}</b><span>cold-retry success</span></div></div><div class="ss-week-bars">${acts.map(x=>`<div><i><b style="height:${Math.max(4,Math.round((x.questions||0)/maxQ*100))}%"></b></i><span>${x.d.slice(5)}</span><small>${x.questions||0}</small></div>`).join('')}</div><div class="ss-coach-grid"><div class="ss-block"><b>⚠️ High-confidence misses</b><p>${danger.length?`${danger.length} question${danger.length===1?'':'s'} you marked “Sure” have still been missed. Prioritize these.`:'None tagged yet. Use confidence buttons after Learn/Review questions.'}</p></div><div class="ss-block"><b>🧠 Cold retrieval</b><p>${retries.length?`${retries.length} blind retest${retries.length===1?'':'s'} this week · ${retryRate}% correct.`:'No blind retests this week. Add a few delayed retries instead of rereading explanations.'}</p></div></div><h3>Top repeated misses</h3><div class="ss-list">${errs.length?errs.map(x=>`<div class="ss-list-item"><div class="ss-grow"><b>${x.type==='listening'?'Listening':'Reading'} ${x.number} · Q${x.q+1}</b><small>Missed ${x.misses}× across saved attempts</small></div><button class="ss-secondary ss-mini" data-report-retest="${esc(x.id)}" data-report-q="${x.q}">Blind retest</button></div>`).join(''):'<div class="ss-empty">No saved repeated misses yet.</div>'}</div><div class="ss-block"><b>Next-week rule</b><p>${danger.length?'Start with high-confidence misses before doing new mocks.':errs.length?'Retest repeated misses after a delay, then do targeted drills on the cause.':'Keep a balanced mix of full mocks, delayed review, speaking and writing production.'}</p></div>`,modal=>$$('[data-report-retest]',modal).forEach(b=>b.onclick=()=>{closeLab($('.ss-modal-back'));openBlindRetry(b.dataset.reportRetest,+b.dataset.reportQ)}))}
function openStudyPlan(){const weak=scoreStats().weakest,reason=mistakeReasonStats()[0]?.reason;const focus=weak==='Listening'?'Listening':weak==='Reading'?'Reading':'mixed comprehension';const cause=reason?reasonLabel(reason):'your next repeated error';const days=daysUntilExam();openLabModal('45-minute focused session','A simple high-yield session based on your saved data',`<div class="ss-plan"><div><b>0–5 min · Retrieval warm-up</b><p>Review 5 due phrase cards or yesterday’s notes without looking at answers first.</p></div><div><b>5–20 min · ${esc(focus)} accuracy block</b><p>Use Smart drill. For every miss, tag the cause. Do not rush to the explanation.</p></div><div><b>20–30 min · Repair the pattern</b><p>Focus on <b>${esc(cause)}</b>. Listening: real-audio dictation + shadowing. Reading: locate the exact sentence that proves the answer.</p></div><div><b>30–40 min · Production</b><p>Alternate by day: one timed speaking task or one writing task. Self-check structure, grammar, vocabulary and appropriateness.</p></div><div><b>40–45 min · Retest</b><p>Redo 3 previously missed questions cold. If correct, schedule them later instead of immediately repeating again.</p></div></div>${days!=null?`<p class="ss-coach-tip">Exam countdown: <b>${days} day${days===1?'':'s'}</b>. ${days<=14?'Prioritize timed full mocks plus targeted repair; avoid learning huge amounts of new material.':'Keep building accuracy and spaced recall before increasing full simulations.'}</p>`:''}`)}

