function keyboard(e){if(e.defaultPrevented||e.metaKey||e.ctrlKey||e.altKey)return;const tag=e.target?.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||e.target?.isContentEditable)return;const mode=currentMode();if(e.key==='?'){e.preventDefault();openDrawer('today');return}if((mode==='learning'||mode==='review')&&(e.key==='b'||e.key==='B')){e.preventDefault();toggleBookmark();return}if(mode==='learning'&&(e.key==='r'||e.key==='R')){const b=$('[data-reveal]');if(b){e.preventDefault();b.click();return}}if((mode==='learning'||mode==='review'||mode==='exam')&&e.key==='ArrowLeft'){const b=$('[data-lprev]')||$('[data-rprev]')||$('[data-prev]');if(b&&!b.disabled){e.preventDefault();b.click();return}}if((mode==='learning'||mode==='review'||mode==='exam')&&e.key==='ArrowRight'){const b=$('[data-lnext]')||$('[data-rnext]')||$('[data-next]');if(b&&!b.disabled){e.preventDefault();b.click();return}}if((mode==='learning'||mode==='exam')&&/^[a-dA-D]$/.test(e.key)){const i=e.key.toUpperCase().charCodeAt(0)-65,b=$(mode==='learning'?`[data-lanswer="${i}"]`:`[data-answer="${i}"]`);if(b){e.preventDefault();b.click()}}}
document.addEventListener('keydown',keyboard);
document.addEventListener('click',e=>{if(e.target.closest('[data-answer],[data-lanswer],[data-reveal]'))markActivity('question');else if(e.target.closest('[data-rnext],[data-lnext],[data-next],[data-resource],[data-guide]'))markActivity('study')},{capture:true});
