/* V7.1 — always-available question navigator with hide/show control. */
(function(){
  'use strict';
  const STORAGE_KEY='tcf-question-nav-hidden-v1';
  let userHidden=false;
  try{userHidden=localStorage.getItem(STORAGE_KEY)==='1'}catch(e){}

  function setStored(v){
    userHidden=!!v;
    try{localStorage.setItem(STORAGE_KEY,userHidden?'1':'0')}catch(e){}
  }

  function showButtonFor(layout){
    let b=document.getElementById('ss-side-show');
    if(!b){
      b=document.createElement('button');
      b.id='ss-side-show';
      b.className='ss-side-show';
      b.type='button';
      b.innerHTML='<span aria-hidden="true">☰</span><span>Show questions</span>';
      b.setAttribute('aria-label','Show question navigator');
      document.body.appendChild(b);
    }
    b.onclick=()=>setCollapsed(layout,false,true);
    return b;
  }

  function setCollapsed(layout,collapsed,remember=false){
    if(!layout)return;
    const side=layout.querySelector(':scope > .side');
    if(!side)return;
    layout.classList.toggle('ss-nav-collapsed',!!collapsed);
    side.classList.toggle('ss-nav-collapsed',!!collapsed);
    side.setAttribute('aria-hidden',collapsed?'true':'false');
    const show=showButtonFor(layout);
    show.classList.toggle('visible',!!collapsed);
    show.setAttribute('aria-hidden',collapsed?'false':'true');
    if(remember)setStored(collapsed);
    if(!collapsed){
      requestAnimationFrame(()=>{
        const current=side.querySelector('.qnav .current,[data-rnav] button[style*="scale(1.06)"],.qnav button.current');
        if(current)current.scrollIntoView({block:'nearest',inline:'nearest'});
      });
    }
  }

  function ensureSideNav(){
    const layout=document.querySelector('.layout');
    const side=layout?.querySelector(':scope > .side');
    if(!layout||!side){
      const show=document.getElementById('ss-side-show');
      if(show)show.classList.remove('visible');
      return;
    }
    side.classList.add('ss-sticky-nav');

    let hide=side.querySelector('[data-ss-hide-nav]');
    if(!hide){
      hide=document.createElement('button');
      hide.type='button';
      hide.className='ss-side-hide';
      hide.setAttribute('data-ss-hide-nav','');
      hide.setAttribute('aria-label','Hide question navigator');
      hide.innerHTML='<span aria-hidden="true">◀</span><span>Hide panel</span>';
      side.insertBefore(hide,side.firstChild);
      hide.onclick=()=>setCollapsed(layout,true,true);
    }

    setCollapsed(layout,userHidden,false);

    // Keep the active question visible inside the navigator's own scroll area.
    const current=side.querySelector('.qnav .current');
    if(current&&current!==side._ssLastCurrent){
      side._ssLastCurrent=current;
      requestAnimationFrame(()=>current.scrollIntoView({block:'nearest',inline:'nearest'}));
    }
  }

  // On a narrow/zoomed viewport the navigator becomes an overlay drawer. After
  // jumping to a question, hide it automatically so the question is immediately visible.
  document.addEventListener('click',e=>{
    const jump=e.target.closest('.side [data-jump],.side [data-ljump],.side [data-rjump]');
    if(!jump)return;
    const layout=jump.closest('.layout');
    if(window.innerWidth<=900){
      setTimeout(()=>setCollapsed(layout,true,false),40);
    }
  },true);

  const obs=new MutationObserver(()=>requestAnimationFrame(ensureSideNav));
  const app=document.getElementById('app')||document.body;
  obs.observe(app,{childList:true,subtree:true});
  window.addEventListener('resize',()=>requestAnimationFrame(ensureSideNav),{passive:true});
  ensureSideNav();
})();
